base <- "analysis/comp_assessments"; db <- file.path(base, "database")
cache <- file.path(base, "source_cache/ck_ices_wgbfas_morhua_bs_25_32/assessment_2026")
id <- "ices_cod_eastern_baltic_2026"; stock_id <- "ck_ices_wgbfas_morhua_bs_25_32"
sag <- "https://sag.ices.dk/SAG_API/StockXmlDownload/22502"; report <- "https://doi.org/10.17895/ices.pub.32455056"
verify <- function(file, hash) {
 p <- file.path(cache, file); actual <- digest::digest(readBin(p, "raw", n=file.info(p)$size), serialize=FALSE, algo="sha256")
 stopifnot(identical(actual, hash)); p
}
invisible(verify("WGBFAS_2026.pdf", "7e8a6ac51f72abf7d1f026e0997f764267f07690cb2b78e32e073e13fd658732"))
xml <- xml2::read_xml(verify("SAG_2026_key_22502.xml", "78c024d457264d59a1670dee044ccf0c196ccdb5a187ce0bcc86fc66d5e1fb72"))
stopifnot(xml2::xml_text(xml2::xml_find_first(xml,"/Assessment/StockCode")) == "cod.27.24-32", xml2::xml_text(xml2::xml_find_first(xml,"/Assessment/AssessmentYear")) == "2026", xml2::xml_text(xml2::xml_find_first(xml,"/Assessment/StockSizeDescription")) == "B_index")
fish <- xml2::xml_find_all(xml,"/Assessment/Fish_Data")
field <- function(x) suppressWarnings(as.numeric(xml2::xml_text(xml2::xml_find_first(fish,x))))
year <- field("Year"); index <- field("StockSize"); land <- field("Landings"); disc <- field("Discards"); small <- field("CustomSeries1"); large <- field("CustomSeries2")
stopifnot(identical(as.integer(year),1946:2025), identical(as.integer(year[is.finite(index)]),1991:2025), all(is.finite(land)), identical(as.integer(year[is.finite(disc)]),1966:2025), all(abs(small[is.finite(index)] + large[is.finite(index)] - index[is.finite(index)]) < .001), tail(index,1)==19.027,tail(land,1)==481,tail(disc,1)==5.1)
blank <- function(file,n=1L) { fields <- names(read.csv(file.path(db,file),nrows=0)); z <- as.data.frame(matrix("",n,length(fields)),stringsAsFactors=FALSE); names(z)<-fields; if("assessment_id" %in% fields) z$assessment_id<-id; z }
input <- function(type, measure, basis, value, unit, notes, survey="", fleet="") {
 ok <- is.finite(value); z <- blank("inputs.csv",sum(ok)); z$type<-type; z$measure<-measure; z$basis<-basis; z$year<-year[ok]; z$year_basis<-"calendar_year"; z$value<-value[ok]; z$unit<-unit; z$survey<-survey; z$fleet<-fleet; z$region<-"Eastern Baltic cod, subdivisions 24-32"; z$source_type<-"official_machine_readable"; z$source_reference<-sag; z$notes<-notes; z
}
inputs <- rbind(input("catch","landings_biomass","biomass",land,"tonnes","ICES estimated landings of eastern stock in SD24 and SD25-32. Historical fishing removals are context, not an age-structured likelihood; 2022-2025 Russian landings are missing per report.",fleet="Total landings"), input("catch","discard_biomass","biomass",disc,"tonnes","ICES estimated discards for eastern stock in SD24 and SD25-32. Missing years are not zero; recent sampling and reporting are incomplete.",fleet="Total discards"), input("index","relative_biomass_index","index_scale",index,"kg/hour","GAM-standardized combined BITS Q1/Q4 biomass index; kg per hour per SAG source data. Annual weight-at-length converts the numbers-at-length index to biomass. Q1 and Q4 cannot be separated from the combined value. This same series is the reported stock indicator.",survey="BITS Q1/Q4 combined"))
ok <- is.finite(index); out <- blank("outputs.csv",sum(ok)); out$type<-"index"; out$measure<-"survey_biomass_index"; out$year<-year[ok]; out$value<-index[ok]; out$unit<-"kg/hour"; out$survey<-"BITS Q1/Q4 combined"; out$region<-"Eastern Baltic cod, subdivisions 24-32"; out$source_type<-"official_machine_readable"; out$source_reference<-sag; out$notes<-"Published index-based stock indicator; identical to the input index, not absolute SSB or an independent model estimate."
a<-blank("assumptions.csv",3); a$component<-"assessment"; a$setting<-c("official_method","survey_index","source_limitations"); a$value<-c("ICES category 3.2 survey-index trend assessment", "GAM-standardized combined BITS Q1/Q4 biomass index since 1991", "Insufficient biological data and unreliable recent catches; Russian landings missing 2022-2025"); a$source_reference<-paste(report,"sections 2.1.1 and 2.1.4"); a$notes<-c("2026 advice uses the index, not the exploratory SPiCT or 2024 Stock Synthesis model.","Includes eastern SD24; weight-at-length changes annually. Exact model formula and raw observations not recovered.","No age-specific population estimates; recent discard coverage is incomplete.")
assessment<-blank("assessments.csv"); assessment$stock_id<-stock_id; assessment$assessment_year<-2026; assessment$terminal_year<-2025; assessment$estimate_terminal_year<-2025; assessment$assessment_type<-"annual"; assessment$model_family<-"ICES category 3.2 survey index"; assessment$is_current<-"TRUE"; assessment$is_applied<-"TRUE"; assessment$assessment_url<-report; assessment$data_url<-sag; assessment$assumptions_status<-"partial"; assessment$inputs_status<-"partial"; assessment$outputs_status<-"partial"; assessment$notes<-"Current 2026 index-based assessment for eastern Baltic cod in subdivisions 24-32; terminal year is last published index year. Historical 2024 Stock Synthesis outputs remain separate. Published catch estimates are incomplete and are contextual, not an age likelihood."
old<-read.csv(file.path(db,"assessments.csv"),colClasses="character",na.strings="",check.names=FALSE); old<-old[old$assessment_id=="ices_cod_eastern_baltic_2024",]; stopifnot(nrow(old)==1); old$is_current<-"FALSE"
write_rows <- function(file,z,key) {
 p<-file.path(db,file); contents<-rawToChar(readBin(p,"raw",n=file.info(p)$size)); lines<-strsplit(contents,"\n",fixed=TRUE)[[1]]; sel<-which(startsWith(lines,paste0('"',key,'",'))); stopifnot(identical(names(z),names(read.csv(p,nrows=0)))); tmp<-tempfile(tmpdir=db); on.exit(unlink(tmp),add=TRUE); write.table(z,tmp,sep=",",quote=TRUE,row.names=FALSE,col.names=FALSE,na="",fileEncoding="UTF-8"); repl<-readLines(tmp,encoding="UTF-8",warn=FALSE)
 if(length(sel)){stopifnot(identical(sel,seq.int(min(sel),max(sel)))); repl<-paste0(repl,if(endsWith(lines[sel[1]],"\r")) "\r" else ""); lines<-c(head(lines,min(sel)-1L),repl,tail(lines,length(lines)-max(sel)))} else lines<-c(lines,repl)
 bytes<-charToRaw(paste0(paste(lines,collapse="\n"),if(endsWith(contents,"\n")) "\n" else "")); if(!identical(bytes,charToRaw(contents))){writeBin(bytes,tmp); if(!file.copy(tmp,p,overwrite=TRUE))stop("write failed")}
}
if(identical(Sys.getenv("TAM_SOURCE_DRY_RUN"),"1")) cat("Eastern Baltic 2026:",nrow(inputs),"inputs and",nrow(out),"reported indices checked.\n") else {write_rows("assessments.csv",old,"ices_cod_eastern_baltic_2024"); write_rows("assessments.csv",assessment,id); write_rows("assumptions.csv",a,id); write_rows("inputs.csv",inputs,id); write_rows("outputs.csv",out,id); cat("Imported current Eastern Baltic 2026 assessment.\n")}
